<?php require __DIR__.'/../app.php';[$w,$t,$a]=bb_owner();$orders=bb_rows('SELECT * FROM transactions WHERE '.$w.' ORDER BY transaction_id DESC',$t,$a);$order=null;$items=[];$id=(int)($_GET['id'] ?? 0);
if($id){$order=bb_one('SELECT * FROM transactions WHERE transaction_id=? AND '.$w,'i'.$t,array_merge([$id],$a));if(!$order) http_response_code(404);else $items=bb_rows('SELECT ti.*,b.title,b.image FROM transaction_items ti JOIN books b ON b.book_id=ti.book_id WHERE transaction_id=?','i',[$id]);}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders | BookBang</title><link rel="stylesheet" href="../backend.css"></head><body><?php include __DIR__.'/../navbar.php'; ?><main class="bb-panel">
<?php if($id&&!$order): ?><h1>Order not found</h1><p>This order is not available in your account or browser session.</p><?php elseif($order): $data=json_decode($order['payment_data'] ?? '{}',true) ?: []; ?><h1>Order #<?= $id ?></h1><p>Status: <strong><?= bb_h(ucfirst($data['status'] ?? 'pending')) ?></strong></p><p>Payment: <?= $order['payment_method']==='cod'?'Cash on Delivery':bb_h($order['payment_method']) ?> · <?= bb_h(ucfirst($data['payment_status'] ?? 'unpaid')) ?></p><p>Delivery to: <?= bb_h($order['first_name'].' '.$order['last_name']) ?></p><p><?= bb_h($data['address'] ?? '') ?>, <?= bb_h($data['city'] ?? '') ?> <?= bb_h($data['postal_code'] ?? '') ?></p><p><?= bb_h($order['email']) ?> · <?= bb_h($order['phone']) ?></p>
<?php foreach($items as $item): ?><div class="bb-item"><img src="<?= bb_h(bookbang_url($item['image'])) ?>" alt="<?= bb_h($item['title']) ?>"><span class="bb-title"><?= bb_h($item['title']) ?> x <?= (int)$item['qty'] ?></span><strong>₱<?= number_format($item['price']*$item['qty'],2) ?></strong></div><?php endforeach; ?><h2>Total: ₱<?= number_format($order['total'],2) ?></h2><p><a href="order.php">All orders</a></p>
<?php else: ?><h1>Your orders</h1><?php if(!$orders): ?><p>You haven’t placed any orders yet.</p><?php else: ?><table><thead><tr><th>Order</th><th>Total</th><th>Payment</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach($orders as $o): $d=json_decode($o['payment_data'] ?? '{}',true) ?: []; ?><tr><td>#<?= (int)$o['transaction_id'] ?></td><td>₱<?= number_format($o['total'],2) ?></td><td><?= $o['payment_method']==='cod'?'COD':bb_h($o['payment_method']) ?></td><td><?= bb_h($d['status'] ?? 'pending') ?></td><td><a href="order.php?id=<?= (int)$o['transaction_id'] ?>">View</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><?php endif; ?><?php if(!bb_user_id()): ?><p>Guest orders are available in this browser session. Create an account to keep them in your account history.</p><?php endif; ?></main></body></html>
